 boolean samePlace(Place a,Place b){return a!=null&&b!=null&&Math.abs(a.lat-b.lat)<.000001&&Math.abs(a.lon-b.lon)<.000001;}
 void changedDraft(){draftChanged=true;loadedRouteId=null;getSharedPreferences("navigation",0).edit().putBoolean("draft_changed",true).apply();persistDraft();syncMaps();}
 void requestClearRoute(){new AlertDialog.Builder(this).setTitle(RideService.running?"结束骑行并清除当前路线？":"清除当前路线？").setMessage("移除当前路线、起终点和途经点。收藏、已保存路线和骑行记录会保留。").setNegativeButton("取消",null).setPositiveButton("清除",(d,n)->{generation++;planning=false;pendingPlan=false;stopLocating();if(RideService.running){stopService(new Intent(this,RideService.class));waitForRideEnd(0);}else clearRouteNow();}).show();}
 void waitForRideEnd(int count){if(!RideService.running){clearRouteNow();return;}if(count>=30){toast("骑行尚未结束，请稍后重试清除");return;}handler.postDelayed(()->waitForRideEnd(count+1),100);}
 void clearRouteNow(){if(RideService.running){toast("请先结束骑行");return;}try{generation++;planning=false;pendingPlan=false;stopLocating();RouteStore.clearActive(this);origin=null;destination=null;via.clear();selected=null;selectedPin=null;loadedRouteId=null;draftChanged=false;originAuto=true;originFixTime=0;preview.follow=false;preview.replayMode=false;preview.replayRunning=false;preview.replayRoute=null;preview.signature="";RideService.outgoing=null;mode="home";mapExpanded=false;lastNote="当前路线已清除，选择地点开始下一程。";showTab("map");toast("已清除当前路线");}catch(Exception e){toast("清除失败："+e.getMessage());}}
 void newRoute(){if(RideService.running){toast("请先结束当前骑行");return;}generation++;pendingPlan=false;stopLocating();origin=null;destination=null;via.clear();originAuto=true;originFixTime=0;selected=null;selectedPin=null;changedDraft();mode="plan";lastNote="请明确选择起点与终点，然后点击规划。";showTab("map");}
 ArrayList<Place> routePoints(){ArrayList<Place> result=new ArrayList<>();if(origin!=null)result.add(origin);result.addAll(via);if(destination!=null)result.add(destination);return result;}
 void setPoint(String target,Place p){if(planning){toast("请先取消当前规划，再修改地点");return;}pendingPlan=false;stopLocating();if(target.equals("via")){if(via.size()>=8){toast("最多添加 8 个途经点");return;}for(Place v:via)if(samePlace(v,p)){toast("该地点已是途经点");return;}if(samePlace(origin,p)||samePlace(destination,p)){toast("这个地点已是起点或终点，无需重复添加");return;}via.add(p);}else{for(int i=via.size()-1;i>=0;i--)if(samePlace(via.get(i),p))via.remove(i);if(target.equals("from")){origin=p;originAuto=false;originFixTime=0;}else destination=p;}changedDraft();lastNote=(target.equals("from")?"起点":target.equals("via")?"途经点":"终点")+"已设为："+p.name+"。请核对上方地点后点击规划。";mode="plan";mapExpanded=false;showTab("map");}
 @Override void select(boolean start,Place p){if(!start){showPlace(p);return;}if(planning||locating==null)return;origin=p;originAuto=p.name.startsWith("当前位置");originFixTime=originAuto?SystemClock.elapsedRealtime():0;pendingPlan=false;stopLocating();changedDraft();lastNote="当前位置已获取，请确认起终点后再次点击规划。";mode="plan";showTab("map");}
 void persistVia(){try{JSONArray a=new JSONArray();for(Place p:via)a.put(new JSONObject().put("name",p.name).put("lat",p.lat).put("lon",p.lon));getSharedPreferences("navigation",0).edit().putString("route_via",a.toString()).putBoolean("draft_changed",true).apply();}catch(Exception ignored){}syncMaps();}
 void persistDraft(){try{android.content.SharedPreferences.Editor e=getSharedPreferences("navigation",0).edit();if(origin!=null)e.putString("origin",new JSONObject().put("name",origin.name).put("lat",origin.lat).put("lon",origin.lon).toString());else e.remove("origin");if(destination!=null)e.putString("destination",new JSONObject().put("name",destination.name).put("lat",destination.lat).put("lon",destination.lon).toString());else e.remove("destination");JSONArray a=new JSONArray();for(Place p:via)a.put(new JSONObject().put("name",p.name).put("lat",p.lat).put("lon",p.lon));e.putString("route_via",a.toString()).apply();}catch(Exception ignored){}}
 void restoreDraft(String id){try{JSONObject draft=db.draft(id);String o=draft.optString("origin"),d=draft.optString("destination");if(!o.isEmpty()){JSONObject p=new JSONObject(o);origin=new Place(p.getString("name"),p.getDouble("lat"),p.getDouble("lon"));}if(!d.isEmpty()){JSONObject p=new JSONObject(d);destination=new Place(p.getString("name"),p.getDouble("lat"),p.getDouble("lon"));}JSONArray a=new JSONArray(draft.optString("via","[]"));for(int i=0;i<a.length();i++){JSONObject p=a.getJSONObject(i);via.add(new Place(p.getString("name"),p.getDouble("lat"),p.getDouble("lon")));}}catch(Exception ignored){}}
